CREATE FUNCTION public.pld_observation_sources(_tenant uuid,_previous timestamptz,_start timestamptz,_end timestamptz) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('payments',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM (SELECT id,gross_amount::text AS amount,paid_at,last_provider_event_id,provider_payment_id,provider_connection_id,status FROM public.payments WHERE tenant_id=_tenant AND provider='asaas' AND paid_at>=_previous AND paid_at<_end ORDER BY paid_at,id LIMIT 10001) p),'[]'::jsonb),'withdrawals',coalesce((SELECT jsonb_agg(to_jsonb(w)) FROM (SELECT id,amount::text AS amount,requested_at FROM public.withdrawals WHERE tenant_id=_tenant AND status NOT IN ('failed','cancelled') AND requested_at>=_start AND requested_at<_end ORDER BY requested_at,id LIMIT 10001) w),'[]'::jsonb),'refunds',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT id,refund_amount::text AS amount,completed_at FROM public.refunds WHERE tenant_id=_tenant AND status='completed' AND completed_at>=_start AND completed_at<_end ORDER BY completed_at,id LIMIT 10001) r),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.pld_observation_sources(uuid,timestamptz,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.pld_observation_sources(uuid,timestamptz,timestamptz,timestamptz) TO service_role;
CREATE FUNCTION public.pld_rule_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Create a new PLD rule version instead'; END $$;
CREATE TRIGGER pld_rules_immutable BEFORE UPDATE OR DELETE ON public.pld_rule_versions FOR EACH ROW EXECUTE FUNCTION public.pld_rule_immutable();
REVOKE ALL ON FUNCTION public.pld_rule_immutable() FROM PUBLIC,anon,authenticated;